<script setup lang="ts">
import type { EChartsOption } from 'echarts'; import { computed } from 'vue'; import EChart from '../components/EChart.vue'; import type { StrategyPerformanceRow } from '../types.js';
const props=defineProps<{rows:readonly StrategyPerformanceRow[]}>(); const money=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});
const chart=computed<EChartsOption>(()=>({grid:{left:50,right:18,top:24,bottom:30},tooltip:{trigger:'axis'},xAxis:{type:'category',data:props.rows.map(r=>r.strategy),axisLabel:{color:'#7890ad'},axisLine:{lineStyle:{color:'#263a55'}}},yAxis:{type:'value',axisLabel:{color:'#7890ad',formatter:(v:number)=>`$${Math.round(v/1000)}k`},splitLine:{lineStyle:{color:'#17263a'}}},series:[{type:'bar',barWidth:26,data:props.rows.map((r,i)=>({value:r.pnlUsd,itemStyle:{color:['#438df5','#3dd6a4','#9d7bf3','#39bfd7','#e9ad55'][i]??'#438df5',borderRadius:[5,5,0,0]}}))}]}));
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">Strategy analytics</p><h2>Strategy Performance</h2><p>Comparative simulated results across the unified graph.</p></div></div><div class="performance-grid"><article class="panel"><div class="panel-title"><div><h3>P&amp;L by strategy</h3><p>30-day simulation</p></div></div><EChart :option="chart" height="300px" /></article><article class="panel performance-summary"><h3>Portfolio summary</h3><div><span>Total simulated P&amp;L</span><strong class="positive">{{ money.format(rows.reduce((sum,row)=>sum+row.pnlUsd,0)) }}</strong></div><div><span>Highest edge</span><strong>S2 · {{ Math.max(...rows.map(r=>r.avgEdgeBps)).toFixed(1) }} bps</strong></div><div><span>Best utilization</span><strong>S2 · {{ (Math.max(...rows.map(r=>r.utilization))*100).toFixed(0) }}%</strong></div></article></div><article class="panel table-panel"><el-table :data="rows"><el-table-column prop="strategy" label="Strategy" width="100"><template #default="scope"><el-tag effect="plain">{{scope.row.strategy}}</el-tag></template></el-table-column><el-table-column prop="name" label="Name" min-width="180"/><el-table-column prop="opportunities" label="Opportunities" align="right"/><el-table-column prop="simulatedTrades" label="Simulated Trades" align="right"/><el-table-column label="P&L" align="right"><template #default="scope"><strong class="positive">{{money.format(scope.row.pnlUsd)}}</strong></template></el-table-column><el-table-column label="Avg Net Edge" align="right"><template #default="scope">{{scope.row.avgEdgeBps.toFixed(1)}} bps</template></el-table-column><el-table-column label="Capital Utilization" min-width="160"><template #default="scope"><el-progress :percentage="scope.row.utilization*100" :stroke-width="7"/></template></el-table-column></el-table></article></section></template>
